import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.XctAhZuT.js";const p=JSON.parse('{"title":"卡片渲染与网络隔离","description":"Anki 卡片可能包含 HTML、CSS、JavaScript、媒体引用和 cloze 模板。Turna 按卡片来源选择渲染路径，脚本与网络是独立权限。","frontmatter":{"description":"Anki 卡片可能包含 HTML、CSS、JavaScript、媒体引用和 cloze 模板。Turna 按卡片来源选择渲染路径，脚本与网络是独立权限。"},"headers":[],"relativePath":"guide/anki-rendering.md","filePath":"guide/anki-rendering.md","lastUpdated":1789373514000}'),i={name:"guide/anki-rendering.md"};function c(r,e,l,n,s,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="卡片渲染与网络隔离" tabindex="-1">卡片渲染与网络隔离 <a class="header-anchor" href="#卡片渲染与网络隔离" aria-label="Permalink to &quot;卡片渲染与网络隔离&quot;">​</a></h1><p>Anki 卡片可能包含 HTML、CSS、JavaScript、媒体引用和 cloze 模板。Turna 按卡片来源选择渲染路径，脚本与网络是独立权限。</p><div class="warning custom-block"><p class="custom-block-title">验收状态</p><p>Official Anki 当前口径是**「验收 NO-GO；迁移中」**，本节描述的 Official 复习器尚未通过生产 bundle 完整用户流验证（Android 写侧仅真机 debug 构建，iOS 仅模拟器 E2E）。详见 <a href="/docs/guide/anki">Anki 集成</a>。</p></div><h2 id="渲染路径" tabindex="-1">渲染路径 <a class="header-anchor" href="#渲染路径" aria-label="Permalink to &quot;渲染路径&quot;">​</a></h2><p>复习入口由 <code>OfficialAnkiReviewerRouter</code> 按来源分发：</p><table tabindex="0"><thead><tr><th>来源</th><th>渲染</th><th>说明</th></tr></thead><tbody><tr><td>Official（正式导入）</td><td>Official 复习器</td><td>模板卡面经 WebView 走原模板渲染；普通卡走结构化 Flutter 卡面</td></tr><tr><td>Legacy（历史数据）</td><td>已退役</td><td>旧版渲染器随 v1 整体退役，非 Official 来源 fail-closed 显示错误</td></tr><tr><td>Turna 练习题</td><td>Flutter 练习</td><td>课程 Interaction 渲染器</td></tr></tbody></table><p>Legacy（v1）已整体退役：Legacy 读路径、卸载链、NoteStore 载荷均已删除，course.db 内的 <code>anki_notetypes</code> / <code>anki_notes</code> / <code>anki_cards_meta</code> 三张表也已 drop。因此不要再指望存在一条仍可处理的「历史数据兼容」通路——遇到非 Official 来源会直接报错。</p><p>题型层面再分两种（见 <a href="/docs/guide/interaction-types">交互题型</a>）：</p><ul><li><code>ankiCard</code> —— 纯文本翻卡（front → back），全平台 Flutter 渲染。</li><li><code>ankiHtmlCard</code> —— 带 <code>frontHtml</code> / <code>backHtml</code> / <code>css</code> / <code>mediaBasePath</code> / <code>allowJs</code> 的保真卡，仅 Official 复习路径用 WebView 按原模板渲染；<strong>课时体与错题回放里该类型的渲染器已退役</strong>（显示「旧版导入的 Anki 卡片」占位，确认后继续）。</li></ul><h2 id="平台差异" tabindex="-1">平台差异 <a class="header-anchor" href="#平台差异" aria-label="Permalink to &quot;平台差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>行为</th></tr></thead><tbody><tr><td>Android</td><td>原生复习器经 MethodChannel/JS 协议，<code>AnkiHtmlCardView</code> 用 WebView 渲染保真卡</td></tr><tr><td>iOS</td><td>原生 WKWebView 复习器（<code>ios/Runner/AnkiReviewer/</code>），自定义 scheme <code>turna-anki://anki.local</code> 提供渲染资产与媒体，与 Android 协议对齐</td></tr><tr><td>桌面 / Web</td><td>不实例化 WebView，降级为剥离标签的纯文本视图</td></tr></tbody></table><p>降级保留可读内容和评分入口，不显示空白卡。</p><blockquote><p>「现场解密 / 预渲染缓存」能力已放弃：<code>anki_prerendered_html</code> 表在 schema v22 就被 drop，相关写入与文案一并删除。排查渲染问题不要再找「预渲染失败记录」。</p></blockquote><h2 id="javascript" tabindex="-1">JavaScript <a class="header-anchor" href="#javascript" aria-label="Permalink to &quot;JavaScript&quot;">​</a></h2><p><code>AnkiHtmlCardView</code> 的 <code>javascriptMode</code> 由两个条件放开：<code>allowJs</code>（notetype 模板含 <code>&lt;script&gt;</code> 时置位）或 <code>typeAnswerEnabled</code>（<code>type:Field</code> 键入模板需要输入桥）。Official 模板卡当前以 <code>allowJs: true</code> 渲染。</p><ul><li>键入卡的答案文本通过 <code>ankiTypeAnswer</code> 通道回传 Flutter —— <strong>评分永不信任页面 JS</strong>。</li><li>JS 关闭的卡不安装任何 JS 通道（包括高度上报）。</li><li>设置 → 旧版与兼容性里有 <code>ankiForceDisableJs</code> 强制关 JS 的兜底开关。</li><li>执行 JavaScript 不等于开放网络，见下节。</li></ul><h2 id="网络隔离" tabindex="-1">网络隔离 <a class="header-anchor" href="#网络隔离" aria-label="Permalink to &quot;网络隔离&quot;">​</a></h2><p>WebView 的 <code>NavigationDelegate</code> 只放行 <code>file:</code> / <code>data:</code> / <code>about:</code> 等本地导航，其余一律 <code>prevent</code> —— 模板脚本无法通过页面跳转访问外部地址。相对路径的 <code>&lt;img&gt;</code> / <code>&lt;audio&gt;</code> 经 <code>&lt;base href=&quot;file:///…&quot;&gt;</code> 解析到该次导入的媒体目录（<code>mediaBasePath</code>）。</p><h2 id="媒体" tabindex="-1">媒体 <a class="header-anchor" href="#媒体" aria-label="Permalink to &quot;媒体&quot;">​</a></h2><ul><li>缺失图片显示占位，不阻塞评分。</li><li>原音频失败时可对卡片文本执行系统 TTS。</li><li><code>cardTextScale</code> 可访问性设置用于放大卡片文本。不同复习器走不同通道：Dart WebView 轨注入 <code>html{zoom}</code>，Android 原生复习器走 <code>WebSettings.textZoom</code>，iOS 原生复习器经 <code>setTextZoom</code>（钳制 100–200）注入 <code>WKUserScript</code>。100% 时不注入，保留原模板样式。</li></ul><h2 id="安全模式" tabindex="-1">安全模式 <a class="header-anchor" href="#安全模式" aria-label="Permalink to &quot;安全模式&quot;">​</a></h2><p>安全模式是系统健康里的运行时覆盖：强制收敛异常行为，但不改写用户保存的设置，退出后恢复进入前的配置。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/anki-import">导入 Anki 牌组</a></li><li><a href="/docs/guide/settings">设置系统</a></li><li><a href="/docs/guide/data-and-privacy">本地数据与隐私</a></li></ul>',24)])])}const b=t(i,[["render",c]]);export{p as __pageData,b as default};
